-- Function: public.sp_assign_organization_role
-- Backup generated on 2026-10-25 20:33:48

CREATE OR REPLACE PROCEDURE public.sp_assign_organization_role(IN p_tenant_id uuid, IN p_organization_id uuid, IN p_user_id uuid, IN p_role_name character varying)  LANGUAGE plpgsql AS $procedure$ BEGIN     INSERT INTO organization_memberships (user_id, organization_id, tenant_id)     SELECT u.id, o.id, o.tenant_id     FROM users u JOIN organizations o ON o.tenant_id = u.tenant_id     WHERE u.id = p_user_id AND u.tenant_id = p_tenant_id AND o.id = p_organization_id     ON CONFLICT DO NOTHING;      INSERT INTO user_organization_roles (user_id, role_id, organization_id, tenant_id)     SELECT p_user_id, r.id, p_organization_id, p_tenant_id     FROM roles r     WHERE r.tenant_id = p_tenant_id AND r.name = p_role_name AND r.scope_type = 'Organization'       AND EXISTS (SELECT 1 FROM organization_memberships m                   WHERE m.user_id = p_user_id AND m.organization_id = p_organization_id AND m.tenant_id = p_tenant_id)     ON CONFLICT DO NOTHING; END; $procedure$ ;
